#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# The wizard reads the human's keyboard. A shell without one (an agent's tool
# call, a `!` prompt prefix, a pipe) would end at the first prompt in silence.
if [[ ! -t 0 ]]; then
  printf 'This wizard needs a keyboard: run it in your own terminal window.\n' >&2
  exit 1
fi

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

# 티켓 26 3절: 업로드 뒤 애드인이 연결된 채로 추가 샘플 요청에 답하고, Fusion을 닫으면 "Fusion 연결 필요"가 되었다가
# 다시 열면 이어지는지 본다(ADR-0013). 요청과 판정은 위저드가 하고, 사람은 Fusion만 끄고 켠다.
# "Fusion 연결 필요"는 서버 요청 상태의 fusion: disconnected로 본다. 실행기의 처리 기록도 그 값에서 나온다(티켓 08).
cd "$(dirname "$0")/.."
SERVER=http://localhost:8000
CHECK_DIR=data/runs/connection-check
SUMMARY="$CHECK_DIR/summary.md"
mkdir -p "$CHECK_DIR"
# 서버의 연결 판정 시간(server/app.py FUSION_TIMEOUT_S, 15초)과 애드인의 요청 찾는 간격(POLL_S, 3초)보다 넉넉히 기다린다
FIRST_WAIT_S=30
DISCONNECT_WAIT_S=60
RECONNECT_WAIT_S=180
UPLOAD_ID=""
WAITED=0
WORD=""
LAST=""
RESULT=""
ANSWER_RESULT="확인 못 함"
DISCONNECT_RESULT="확인 못 함"
RECONNECT_RESULT="확인 못 함"

reader() { PYTHONUTF8=1 .venv/Scripts/python -m scripts.connection_check "$@"; }

# addin_status: 애드인 상태 파일로 고른, 애드인이 지금 이 업로드에 답하는지나 못 하는 까닭 한 줄(티켓 33).
# 끊김이 Fusion이 꺼진 것인지, 주 스레드가 막힌 것인지, 답할 업로드를 모르는 것인지를 사람에게 묻지 않고 가린다.
addin_status() {
  PYTHONUTF8=1 .venv/Scripts/python -m scripts.serving_status data/addin-checks/serving.json "$UPLOAD_ID" \
    || echo "애드인 상태 파일을 읽지 못함"
}

# new_request: 업로드에 추가 샘플 요청 하나를 걸고 요청 ID를 찍는다. 걸지 못하면 아무것도 찍지 않는다.
new_request() {
  rm -f "$CHECK_DIR/request.json" "$CHECK_DIR/created.json"
  reader request "data/uploads/$UPLOAD_ID.json" > "$CHECK_DIR/request.json" || return 0
  curl -sf -m 10 -o "$CHECK_DIR/created.json" -X POST -H "Content-Type: application/json" \
    --data-binary @"$CHECK_DIR/request.json" "$SERVER/uploads/$UPLOAD_ID/sample-requests" || return 0
  reader created "$CHECK_DIR/created.json" || true
}

# state 요청ID: "<상태 낱말> <설명>" 한 줄. 낱말은 scripts/connection_check.py의 STATES와 아래 셋이다.
state() {
  local code
  code=$(curl -s -m 10 -o "$CHECK_DIR/state.json" -w '%{http_code}' "$SERVER/uploads/$UPLOAD_ID/sample-requests/$1" || true)
  case "$code" in
    200) reader state "$CHECK_DIR/state.json" "$CHECK_DIR/request.json" || echo "unreadable 요청 상태를 읽지 못함" ;;
    404) echo "lost 서버에 그 요청이 없다(서버가 다시 떠 메모리의 요청을 잊었을 수 있다)" ;;
    *) echo "noserver 서버 응답 없음(HTTP ${code:-없음})" ;;
  esac
}

# wait_for 요청ID 최대초 낱말…: 상태 낱말이 주어진 것 중 하나가 되거나 요청을 잃을 때까지 3초마다 본다.
# 마지막 상태는 LAST·WORD, 걸린 초는 WAITED에 둔다.
wait_for() {
  local id="$1" limit="$2" start=$SECONDS
  shift 2
  note "기다리는 중(최대 ${limit}초)…"
  while :; do
    LAST=$(state "$id")
    WORD=${LAST%% *}
    WAITED=$((SECONDS - start))
    [[ " $* lost " == *" $WORD "* ]] && return 0
    (( WAITED >= limit )) && return 0
    sleep 3
  done
}

# report 기대낱말 제목: 마지막 상태를 RESULT에 "N초 뒤 <설명>"으로 두고 ✓ 또는 ⚠로 보인다.
# 답하지 않았으면(connected·disconnected) 애드인 상태 파일로 고른 까닭을 덧붙인다.
report() {
  RESULT="${WAITED}초 뒤 ${LAST#* }"
  if [[ "$WORD" == connected || "$WORD" == disconnected ]]; then
    RESULT+=" / 애드인: $(addin_status)"
  fi
  if [[ "$WORD" == "$1" ]]; then say "${GREEN}✓${RESET} $2: $RESULT"; else warn "$2: $RESULT"; fi
}

write_summary() {
  {
    printf '# 업로드 뒤 연결 확인 (%s)\n\n' "$(date '+%Y-%m-%d %H:%M')"
    # shellcheck disable=SC2016  # 작은따옴표 안의 `는 일부러 펼치지 않는다(메모의 마크다운 코드)
    printf -- '- 커밋: `%s`\n' "$(git log -1 --format='%h %s')"
    printf -- '- 업로드 ID: %s\n' "${UPLOAD_ID:-없음}"
    printf -- '- 연결된 채로 답함: %s\n' "$ANSWER_RESULT"
    printf -- '- Fusion을 끈 뒤: %s\n' "$DISCONNECT_RESULT"
    printf -- '- 다시 켠 뒤: %s\n' "$RECONNECT_RESULT"
    printf -- '- 이상했던 점: %s\n' "${ODDITIES:-없음}"
  } > "$SUMMARY"
  say "${GREEN}✓${RESET} 결과를 $SUMMARY 에 썼다."
  say "Claude에게 \"연결 확인 끝\"이라고 알린다."
}

# stop_early 까닭: 앞 단계가 실패해 뒤 단계가 잴 것이 없을 때 그때까지의 결과를 남기고 끝낸다
stop_early() {
  SKIPPED+=("$1")
  ODDITIES="$1"
  write_summary
  finish
  exit 0
}

run_wizard() {

TOTAL_STAGES=4

banner "티켓 26 3절: 업로드 뒤 연결"
stage "연결된 채로 답하는지"
until curl -sf -m 5 -o /dev/null "$SERVER/health"; do
  warn "서버($SERVER)가 답하지 않는다."
  step "Docker Desktop을 켜고 저장소 루트에서 docker compose up -d server 를 돌린다."
  pause "서버를 띄웠으면 Enter"
done
# 애드인은 이 Fusion 세션에서 마지막으로 올린 업로드에만 답한다. 그 업로드 뒤 애드인이 쓴 점검 파일로 고른다
# (건식 업로드와 애드인 상태 파일은 뺀다). 업로드 폴더의 파일 시각은 다른 세션의 업로드와 섞인다.
UPLOAD_ID=$(PYTHONUTF8=1 .venv/Scripts/python -m scripts.addin_checks latest data/addin-checks || true)
[[ -n "$UPLOAD_ID" && -f "data/uploads/$UPLOAD_ID.json" ]] || {
  warn "애드인의 마지막 업로드를 찾지 못했다. 녹화 위저드로 먼저 업로드한다."
  exit 1
}
say "애드인의 마지막 업로드: $UPLOAD_ID"
note "업로드 직후 바로 돌려도 된다. 업로드 완료는 메시지 창 없이 텍스트 명령 창에 찍히므로 애드인이 곧바로 답한다(ADR-0013)."
note "Fusion에 그 문서가 열려 있고 애드인이 실행 중이어야 한다. 애드인은 업로드 ID를 문서에 적어 두므로, 문서를 저장한 뒤라면 Fusion을 껐다 켜거나 애드인을 다시 실행해도 이어 답한다."
pause "Enter를 누르면 요청을 건다"
first=$(new_request)
[[ -n "$first" ]] || stop_early "첫 요청을 걸지 못함"
wait_for "$first" "$FIRST_WAIT_S" answered failed
report answered "연결된 채로 답함"
ANSWER_RESULT="$RESULT"
# 첫 요청에 답하지 않으면 처음부터 끊긴 것이라, 끊김 확인이 늘 통과로 나온다. 거기서 멈춘다.
[[ "$WORD" == answered ]] || stop_early "첫 요청에 답하지 않아 끊김·다시 연결을 잴 수 없음"
pause "Enter"

stage "Fusion 끄기"
step "Fusion에서 문서를 저장한다(Ctrl+S)."
step "Fusion을 완전히 끈다(창 닫기 또는 파일 → 종료). 작업 관리자에서 Fusion이 사라질 때까지 기다린다."
pause "Fusion을 껐으면 Enter"
# 첫 요청은 답을 받았으므로 열린 요청은 이것 하나다. 다시 붙은 애드인이 가장 오래된 요청부터 답해도 이 요청이다.
pending=$(new_request)
[[ -n "$pending" ]] || stop_early "끈 뒤 요청을 걸지 못함"
wait_for "$pending" "$DISCONNECT_WAIT_S" disconnected answered failed
report disconnected "Fusion을 끈 뒤"
DISCONNECT_RESULT="$RESULT"
[[ "$WORD" == disconnected ]] || stop_early "Fusion을 끈 뒤 Fusion 연결 필요가 되지 않아 다시 연결을 잴 수 없음"
pause "Enter"

stage "Fusion 다시 켜기"
note "애드인은 답하던 업로드 ID를 문서에 적어 둔다. 문서가 열려 있고 애드인이 실행 중이면 서버가 그 업로드를 아는 한 알아서 이어 답한다."
step "Fusion을 켜고 방금 저장한 문서를 연다."
step "Shift+S → \"스크립트 및 추가 기능\" 창에서 ConfiguratorUploader를 실행한다(시작할 때 실행은 꺼져 있다)."
step "\"구성기 업로드\"는 누르지 않는다. 새 업로드는 다른 ID라 이어진 것이 아니다."
pause "문서를 열고 애드인을 실행했으면 Enter"
# 연결 신호만 오고 답이 없으면(connected) 끝까지 기다린 뒤 그 상태로 적는다
wait_for "$pending" "$RECONNECT_WAIT_S" answered failed
report answered "다시 켠 뒤"
RECONNECT_RESULT="$RESULT"
pause "Enter"

stage "기록"
ask ODDITIES "그 밖에 이상했던 점(없으면 Enter):"
write_summary
pause "Enter"

finish
}

run_wizard "$@"; exit
